    DROP INDEX IF EXISTS idx_shared_themes_usage_count;
    DROP INDEX IF EXISTS idx_shared_themes_favorite_count;
    DROP INDEX IF EXISTS idx_shared_themes_created_at;
    DROP INDEX IF EXISTS idx_shared_themes_creator;
